import tkinter as tk
from time import sleep

carps = {
    "BIGHEAD CARP": "",
    "BLACK CARP": "",
    "GRASS CARP": "",
    "SILVER CARP": ""
}

def check_dna():
    possible = []
    dna = entry.get().upper().strip()
    
    if dna:
        for name, eDna in carps.items():
            if eDna.startswith(dna):
                possible.append(name)
        if not possible:
            status.config(text="Нет совпадений")
        else:
            status.config(text=f"Совпадения: {', '.join(possible)}")
    else:
        status.config(text="Введите последовательность")
    
    root.after(100, check_dna)

root = tk.Tk()
root.geometry("800x800")
root.title("Принадлежность эДНК")

status = tk.Label(root, text="Введите последовательность", font=("Arial", 20))
entry = tk.Entry(root, font=("Arial", 20))

entry.pack(expand=True, anchor="center")
status.pack(expand=True, anchor="center")

check_dna()

root.mainloop()